SplashScreen.setOptions({ duration: 500, fade: true });
SplashScreen.preventAutoHideAsync().catch(() => undefined);

type RootStackParamList = { AppTabs: undefined; RoomDetail: { roomId: string }; RoomManager: undefined; CheckIn: undefined; ShareBooking: undefined; Waitlist: undefined; Reviews: undefined };
type AppTabParamList = { Browse: undefined; Focus: undefined; Bookings: undefined; Profile: undefined };
const RootStack = createNativeStackNavigator<RootStackParamList>();
const Tabs = createBottomTabNavigator<AppTabParamList>();

function App(): ReactElement {
  const session = useBookingStore((state) => state.session);
  const hasHydrated = useBookingStore((state) => state.hasHydrated);
  const reservations = useBookingStore((state) => state.reservations);
  const syncQueue = useBookingStore((state) => state.syncQueue);
  const clearSyncPending = useBookingStore((state) => state.clearSyncPending);
  const setRemoteRooms = useBookingStore((state) => state.setRemoteRooms);
  const setRemoteReservations = useBookingStore((state) => state.setRemoteReservations);
  const setRemoteWaitlist = useBookingStore((state) => state.setRemoteWaitlist);
  const setRemoteReviews = useBookingStore((state) => state.setRemoteReviews);
  const setAuthSession = useBookingStore((state) => state.setAuthSession);
  const markExpiredReservations = useBookingStore((state) => state.markExpiredReservations);
  const netInfo = useNetInfo();
  const [booted, setBooted] = useState(false);
  const [authReady, setAuthReady] = useState(!isFirebaseConfigured);
  useEffect(() => { if (!isFirebaseConfigured) return undefined; return subscribeToFirebaseAuth((nextSession) => { setAuthSession(nextSession ? { id: nextSession.id, name: nextSession.name, email: nextSession.email, role: nextSession.role, emailVerified: nextSession.emailVerified } : null); setAuthReady(true); }, () => setAuthReady(true)); }, [setAuthSession]);
  useEffect(() => { if (!isFirebaseConfigured) return undefined; return subscribeToFirebaseRooms(setRemoteRooms); }, [setRemoteRooms]);
  useEffect(() => { if (!isFirebaseConfigured || !session?.id) return undefined; return subscribeToFirebaseBookings(session.id, setRemoteReservations); }, [session?.id, setRemoteReservations]);
  useEffect(() => { if (!isFirebaseConfigured || !session?.id) return undefined; return subscribeToFirebaseWaitlist(session.id, setRemoteWaitlist); }, [session?.id, setRemoteWaitlist]);
  useEffect(() => { if (!isFirebaseConfigured || !session?.id) return undefined; return subscribeToFirebaseReviews(session.id, setRemoteReviews); }, [session?.id, setRemoteReviews]);
  useEffect(() => { if (hasHydrated) markExpiredReservations(); }, [hasHydrated, markExpiredReservations]);
  useEffect(() => { if (hasHydrated && netInfo.isConnected === true && syncQueue.length > 0) void syncPendingReservations(reservations, syncQueue, clearSyncPending); }, [clearSyncPending, hasHydrated, netInfo.isConnected, reservations, syncQueue]);
  if (!hasHydrated || !authReady) return <LoadingScreen />;
  if (!booted) return <SafeAreaProvider><BootScreen onComplete={() => { setBooted(true); SplashScreen.hideAsync(); }} /><StatusBar style="light" /></SafeAreaProvider>;
  return <SafeAreaProvider><NavigationContainer><SessionFlow session={session} /></NavigationContainer><StatusBar style={session ? 'dark' : 'light'} /></SafeAreaProvider>;
}

function BootScreen({ onComplete }: { onComplete: () => void }) {
  const progress = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.spring(progress, { toValue: 1, damping: 16, stiffness: 110, useNativeDriver: true }).start();
    const timer = setTimeout(onComplete, 1700);
    return () => clearTimeout(timer);
  }, [onComplete, progress]);
  return <LinearGradient colors={['#061A31', '#0B2A4A', '#0284C7']} style={styles.bootScreen}><MorphScene style={styles.bootMorph} /><Animated.View style={[styles.bootCopy, { opacity: progress, transform: [{ translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [12, 0] }) }] }]}><Text style={styles.bootTitle}>VKU Space</Text><Text style={styles.bootSubtitle}>Your focused campus, in motion.</Text></Animated.View><View style={styles.bootProgress}><Animated.View style={[styles.bootProgressFill, { transform: [{ scaleX: progress }] }]} /></View></LinearGradient>;
}

function SessionFlow({ session }: { session: ReturnType<typeof useBookingStore.getState>['session'] }) {
  const progress = useRef(new Animated.Value(0)).current;
  useEffect(() => { progress.setValue(0); Animated.spring(progress, { toValue: 1, damping: 18, stiffness: 130, useNativeDriver: true }).start(); }, [progress, session]);
  return <Animated.View style={{ flex: 1, opacity: progress, transform: [{ scale: progress.interpolate({ inputRange: [0, 1], outputRange: [0.98, 1] }) }] }}>{session ? <AppNavigator /> : <AuthScreen />}</Animated.View>;
}

function LoadingScreen() {
  return <LinearGradient colors={['#09233F', '#0284C7']} style={styles.loadingScreen}><View style={styles.brandMark}><Ionicons name="scan-outline" size={27} color={colors.white} /></View><Text style={styles.loadingTitle}>VKU Space</Text><ActivityIndicator color={colors.white} style={styles.loadingIndicator} /></LinearGradient>;
}

function AppNavigator() {
  return <RootStack.Navigator screenOptions={{ headerShown: false, animation: 'fade' }}><RootStack.Screen name="AppTabs" component={AppTabs} /><RootStack.Screen name="RoomDetail" component={RoomDetailScreen} /><RootStack.Screen name="RoomManager" component={AdminDashboardScreen} /><RootStack.Screen name="CheckIn" component={CheckInScreen} /><RootStack.Screen name="ShareBooking" component={ShareBookingScreen} /><RootStack.Screen name="Waitlist" component={WaitlistScreen} /><RootStack.Screen name="Reviews" component={ReviewsScreen} /></RootStack.Navigator>;
}

function AppTabs() {
  return <Tabs.Navigator screenOptions={({ route }) => ({
    headerShown: false, tabBarActiveTintColor: colors.primary, tabBarInactiveTintColor: '#94A3B8',
    tabBarLabelStyle: styles.tabBarLabel, tabBarStyle: styles.tabBar,
    tabBarIcon: ({ color, size, focused }) => {
      const icon = route.name === 'Browse' ? focused ? 'compass' : 'compass-outline' : route.name === 'Focus' ? focused ? 'flash' : 'flash-outline' : route.name === 'Bookings' ? focused ? 'calendar' : 'calendar-outline' : focused ? 'person' : 'person-outline';
      return <Ionicons name={icon as keyof typeof Ionicons.glyphMap} color={color} size={size} />;
    },
  })}><Tabs.Screen name="Browse" component={BrowseScreen} options={{ tabBarLabel: 'Khám phá' }} /><Tabs.Screen name="Focus" component={FocusScreen} options={{ tabBarLabel: 'Tập trung' }} /><Tabs.Screen name="Bookings" component={BookingsScreen} options={{ tabBarLabel: 'Lịch đặt' }} /><Tabs.Screen name="Profile" component={ProfileScreen} options={{ tabBarLabel: 'Hồ sơ' }} /></Tabs.Navigator>;
}

function AuthScreen() {
  const login = useBookingStore((state) => state.login); const register = useBookingStore((state) => state.register); const setAuthSession = useBookingStore((state) => state.setAuthSession);
  const [mode, setMode] = useState<'login' | 'register'>('login'); const [name, setName] = useState(''); const [email, setEmail] = useState('student@vku.udn.vn'); const [password, setPassword] = useState('123456'); const [showPassword, setShowPassword] = useState(false); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const blobProgress = useRef(new Animated.Value(0)).current; const formProgress = useRef(new Animated.Value(0)).current;
  useEffect(() => { Animated.loop(Animated.sequence([Animated.timing(blobProgress, { toValue: 1, duration: 3600, useNativeDriver: true }), Animated.timing(blobProgress, { toValue: 0, duration: 3600, useNativeDriver: true })])).start(); Animated.spring(formProgress, { toValue: 1, useNativeDriver: true, damping: 16, stiffness: 120 }).start(); }, [blobProgress, formProgress]);
  const blobOneStyle = { transform: [{ translateX: blobProgress.interpolate({ inputRange: [0, 1], outputRange: [-8, 20] }) }, { translateY: blobProgress.interpolate({ inputRange: [0, 1], outputRange: [0, 26] }) }, { scale: blobProgress.interpolate({ inputRange: [0, 1], outputRange: [1, 1.13] }) }] };
  const blobTwoStyle = { transform: [{ translateX: blobProgress.interpolate({ inputRange: [0, 1], outputRange: [16, -18] }) }, { translateY: blobProgress.interpolate({ inputRange: [0, 1], outputRange: [10, -16] }) }, { scale: blobProgress.interpolate({ inputRange: [0, 1], outputRange: [1, 0.86] }) }] };
  const submit = async () => {
    setError(''); if (!email.includes('@')) return setError('Nhập email hợp lệ để tiếp tục.'); if (password.length < 6) return setError('Mật khẩu cần ít nhất 6 ký tự.'); if (mode === 'register' && name.trim().length < 2) return setError('Tên cần ít nhất 2 ký tự.');
    setBusy(true);
    try {
      if (isFirebaseConfigured) {
        const nextSession = mode === 'login' ? await loginWithFirebase(email, password) : await registerWithFirebase(name, email, password);
        setAuthSession({ id: nextSession.id, name: nextSession.name, email: nextSession.email, role: nextSession.role, emailVerified: nextSession.emailVerified });
      } else {
        await new Promise((resolve) => setTimeout(resolve, 280));
        if (mode === 'login') login(email, name.trim() || undefined); else register(name.trim(), email);
      }
    } catch (authError) {
      setError(authError instanceof Error ? authError.message : 'Không thể đăng nhập.');
    } finally { setBusy(false); }
  };
  const resetPassword = async () => {
    if (!email.includes('@')) { setError('Nhập email hợp lệ trước khi đặt lại mật khẩu.'); return; }
    if (!isFirebaseConfigured) { Alert.alert('Chế độ demo', 'Reset mật khẩu sẽ hoạt động sau khi cấu hình Firebase Authentication.'); return; }
    setBusy(true); setError(''); try { await resetFirebasePassword(email); Alert.alert('Đã gửi email', 'Kiểm tra hộp thư để đặt lại mật khẩu.'); } catch (authError) { setError(authError instanceof Error ? authError.message : 'Không thể gửi email reset.'); } finally { setBusy(false); }
  };
  return <LinearGradient colors={['#09233F', '#0B3C64', '#0284C7']} style={styles.authScreen}><Animated.View style={[styles.morphBlob, styles.morphBlobOne, blobOneStyle]} /><Animated.View style={[styles.morphBlob, styles.morphBlobTwo, blobTwoStyle]} /><SafeAreaView style={styles.authSafeArea} edges={['top', 'bottom']}><KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.flexOne}><ScrollView contentContainerStyle={styles.authContent} keyboardShouldPersistTaps="handled"><View style={styles.authBrandRow}><View style={styles.authBrandIcon}><Ionicons name="scan-outline" size={25} color={colors.white} /></View><Text style={styles.authBrand}>VKU Space</Text></View><Text style={styles.authEyebrow}>CAMPUS PRODUCTIVITY</Text><Text style={styles.authTitle}>Tìm góc học tập{`\n`}của riêng bạn.</Text><Text style={styles.authSubtitle}>Đặt phòng học VKU nhanh gọn, kể cả khi đang offline.</Text><Animated.View style={[styles.authCard, { opacity: formProgress, transform: [{ translateY: formProgress.interpolate({ inputRange: [0, 1], outputRange: [22, 0] }) }] }]}><View style={styles.authSwitch}><AuthModeButton label="Đăng nhập" active={mode === 'login'} onPress={() => { setMode('login'); setError(''); }} /><AuthModeButton label="Tạo tài khoản" active={mode === 'register'} onPress={() => { setMode('register'); setError(''); }} /></View>{mode === 'register' ? <Field label="Họ và tên" value={name} onChangeText={setName} placeholder="Nguyễn Văn A" icon="person-outline" /> : null}<Field label="Email sinh viên" value={email} onChangeText={setEmail} placeholder="you@vku.udn.vn" keyboardType="email-address" autoCapitalize="none" icon="mail-outline" /><Field label="Mật khẩu" value={password} onChangeText={setPassword} placeholder="••••••••" secureTextEntry={!showPassword} icon="lock-closed-outline" right={<Pressable onPress={() => setShowPassword((value) => !value)} hitSlop={8} accessibilityLabel={showPassword ? 'Ẩn mật khẩu' : 'Hiện mật khẩu'}><Ionicons name={showPassword ? 'eye-off-outline' : 'eye-outline'} size={21} color={colors.inkMuted} /></Pressable>} />{mode === 'login' ? <Pressable onPress={() => void resetPassword()} style={styles.forgotButton} accessibilityRole="button"><Text style={styles.forgotText}>Quên mật khẩu?</Text></Pressable> : null}{error ? <Text style={styles.formError}>{error}</Text> : null}<Pressable onPress={() => void submit()} disabled={busy} style={({ pressed }) => [styles.primaryButton, pressed && styles.pressed, busy && styles.disabledButton]} accessibilityRole="button">{busy ? <ActivityIndicator color={colors.white} /> : <><Text style={styles.primaryButtonText}>{mode === 'login' ? 'Đăng nhập' : 'Tạo tài khoản'}</Text><Ionicons name="arrow-forward" size={19} color={colors.white} /></>}</Pressable><Text style={styles.authHint}>{isFirebaseConfigured ? 'Tài khoản được bảo vệ bằng Firebase Authentication.' : 'Chế độ demo local: cấu hình Firebase để bật tài khoản thật.'}</Text></Animated.View></ScrollView></KeyboardAvoidingView></SafeAreaView></LinearGradient>;
}

function AuthModeButton({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) { return <Pressable onPress={onPress} style={[styles.authModeButton, active && styles.authModeButtonActive]} accessibilityRole="tab" accessibilityState={{ selected: active }}><Text style={[styles.authModeText, active && styles.authModeTextActive]}>{label}</Text></Pressable>; }

function Field(props: { label: string; value: string; onChangeText: (text: string) => void; placeholder: string; icon: keyof typeof Ionicons.glyphMap; secureTextEntry?: boolean; keyboardType?: 'default' | 'email-address'; autoCapitalize?: 'none' | 'sentences'; right?: React.ReactNode }) {
  const { label, icon, right, ...inputProps } = props;
  return <View style={styles.fieldGroup}><Text style={styles.fieldLabel}>{label}</Text><View style={styles.fieldInputRow}><Ionicons name={icon} size={19} color={colors.primary} /><TextInput {...inputProps} style={styles.fieldInput} placeholderTextColor="#94A3B8" autoCorrect={false} returnKeyType="done" />{right}</View></View>;
}

function ScreenMotion({ children, style }: { children: React.ReactNode; style?: StyleProp<ViewStyle> }) { const progress = useRef(new Animated.Value(0)).current; useEffect(() => { Animated.spring(progress, { toValue: 1, useNativeDriver: true, damping: 18, stiffness: 130 }).start(); }, [progress]); return <Animated.View style={[style, { flex: 1, opacity: progress, transform: [{ translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [12, 0] }) }] }]}>{children}</Animated.View>; }
function useRoomCatalog() { const roomOverrides = useBookingStore((state) => state.roomOverrides); const customRooms = useBookingStore((state) => state.customRooms); const remoteRooms = useBookingStore((state) => state.remoteRooms); const hiddenRoomIds = useBookingStore((state) => state.hiddenRoomIds); return useMemo(() => { const byId = new Map([...rooms, ...customRooms, ...remoteRooms].map((room) => [room.id, room])); return [...byId.values()].filter((room) => !hiddenRoomIds.includes(room.id)).map((room) => ({ ...room, ...roomOverrides[room.id] })); }, [customRooms, hiddenRoomIds, remoteRooms, roomOverrides]); }

function BrowseScreen() {
  const navigation = useNavigation<NativeStackScreenProps<RootStackParamList, 'AppTabs'>['navigation']>(); const netInfo = useNetInfo();
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions(); const isWide = width >= 700;
  const catalog = useRoomCatalog();
  const [query, setQuery] = useState(''); const [building, setBuilding] = useState<Building | 'All'>('All'); const [capacity, setCapacity] = useState<'All' | 'Small' | 'Medium' | 'Large'>('All'); const [equipment, setEquipment] = useState<'All' | Room['equipment'][number]>('All');
  const filteredRooms = useMemo(() => catalog.filter((room) => { const q = query.toLowerCase().trim(); const matchesQuery = !q || `${room.name} ${room.building} ${room.description}`.toLowerCase().includes(q); const matchesBuilding = building === 'All' || room.building === building; const matchesCapacity = capacity === 'All' || (capacity === 'Small' ? room.capacity <= 6 : capacity === 'Medium' ? room.capacity <= 12 : room.capacity > 12); const matchesEquipment = equipment === 'All' || room.equipment.includes(equipment); return matchesQuery && matchesBuilding && matchesCapacity && matchesEquipment; }), [building, capacity, catalog, equipment, query]);
  return <ScreenMotion><SafeAreaView style={styles.appScreen} edges={['top']}><FlatList data={filteredRooms} keyExtractor={(item) => item.id} numColumns={isWide ? 2 : 1} columnWrapperStyle={isWide ? responsiveStyles.roomColumn : undefined} style={isWide ? responsiveStyles.roomListWide : undefined} ListHeaderComponent={<FlatListHeader query={query} setQuery={setQuery} building={building} setBuilding={setBuilding} capacity={capacity} setCapacity={setCapacity} equipment={equipment} setEquipment={setEquipment} roomCount={filteredRooms.length} online={netInfo.isConnected !== false} wide={isWide} />} renderItem={({ item, index }) => <RoomCard room={item} index={index} wide={isWide} onPress={() => navigation.navigate('RoomDetail', { roomId: item.id })} />} ItemSeparatorComponent={() => <View style={{ height: spacing.md }} />} ListEmptyComponent={<EmptyState />} contentContainerStyle={[styles.roomListContent, isWide && responsiveStyles.roomListContentWide, { paddingBottom: Math.max(112, insets.bottom + 96) }]} showsVerticalScrollIndicator={false} initialNumToRender={6} maxToRenderPerBatch={4} windowSize={5} removeClippedSubviews /></SafeAreaView></ScreenMotion>;
}

function FlatListHeader(props: { query: string; setQuery: (value: string) => void; building: Building | 'All'; setBuilding: (value: Building | 'All') => void; capacity: 'All' | 'Small' | 'Medium' | 'Large'; setCapacity: (value: 'All' | 'Small' | 'Medium' | 'Large') => void; equipment: 'All' | Room['equipment'][number]; setEquipment: (value: 'All' | Room['equipment'][number]) => void; roomCount: number; online: boolean; wide: boolean }) {
  return <View style={[styles.listHeader, props.wide && responsiveStyles.listHeaderWide]}><HomeHero /><View style={styles.topBar}><View><Text style={styles.kicker}>VKU SPACE</Text><Text style={styles.screenTitle}>Tìm phòng học</Text></View><View style={[styles.onlinePill, !props.online && styles.offlinePill]}><View style={[styles.statusDot, !props.online && styles.offlineDot]} /><Text style={[styles.onlineText, !props.online && styles.offlineText]}>{props.online ? 'Đã đồng bộ' : 'Đang offline'}</Text></View></View><Text style={styles.welcomeText}>Không gian tốt, tập trung tốt hơn.</Text><View style={styles.searchBox}><Ionicons name="search-outline" size={21} color={colors.inkMuted} /><TextInput value={props.query} onChangeText={props.setQuery} placeholder="Tìm theo tên, tòa nhà..." placeholderTextColor="#94A3B8" style={styles.searchInput} returnKeyType="search" autoCapitalize="none" accessibilityLabel="Tìm kiếm phòng" />{props.query ? <Pressable onPress={() => props.setQuery('')} hitSlop={8} accessibilityLabel="Xóa tìm kiếm"><Ionicons name="close-circle" size={19} color="#94A3B8" /></Pressable> : null}</View><Text style={styles.sectionLabel}>TÒA NHÀ</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chipRow}>{(['All', 'A', 'B', 'C', 'V'] as const).map((item) => <FilterChip key={item} label={item === 'All' ? 'Tất cả' : `Tòa ${item}`} active={props.building === item} onPress={() => props.setBuilding(item)} />)}</ScrollView><Text style={styles.sectionLabel}>SỨC CHỨA</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chipRow}>{(['All', 'Small', 'Medium', 'Large'] as const).map((item) => <FilterChip key={item} label={item === 'All' ? 'Tất cả' : item === 'Small' ? '2–6 chỗ' : item === 'Medium' ? '7–12 chỗ' : '13–20 chỗ'} active={props.capacity === item} onPress={() => props.setCapacity(item)} />)}</ScrollView><Text style={styles.sectionLabel}>THIẾT BỊ</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chipRow}>{(['All', 'Projector', 'Whiteboard', 'High-spec PC', 'AC'] as const).map((item) => <FilterChip key={item} label={item === 'All' ? 'Tất cả' : item === 'High-spec PC' ? 'PC cấu hình cao' : item} active={props.equipment === item} onPress={() => props.setEquipment(item)} />)}</ScrollView><View style={styles.resultRow}><Text style={styles.resultCount}>{props.roomCount} phòng phù hợp</Text><View style={styles.liveLabel}><Ionicons name="pulse-outline" size={15} color={colors.mint} /><Text style={styles.liveText}>Trạng thái live</Text></View></View></View>;
}

function HomeHero() {
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const { width } = useWindowDimensions();
  const isWide = width >= 700;
  const catalog = useRoomCatalog();
  const reservations = useBookingStore((state) => state.reservations);
  const createReservation = useBookingStore((state) => state.createReservation);
  const favoriteRoomIds = useBookingStore((state) => state.favoriteRoomIds);
  const toggleFavorite = useBookingStore((state) => state.toggleFavorite);
  const [goal, setGoal] = useState<'quiet' | 'team' | 'project' | 'pc'>('quiet');
  const goalLabel = goal === 'quiet' ? 'Tập trung yên tĩnh' : goal === 'team' ? 'Học nhóm' : goal === 'project' ? 'Làm project' : 'PC cấu hình cao';
  const recommended = useMemo(() => catalog.find((room) => room.status === 'available' && (goal === 'quiet' ? room.capacity <= 6 : goal === 'team' ? room.capacity >= 8 : goal === 'project' ? room.equipment.includes('Projector') : room.equipment.includes('High-spec PC'))) || catalog.find((room) => room.status === 'available') || catalog[0], [catalog, goal]);
  const isFavorite = Boolean(recommended && favoriteRoomIds.includes(recommended.id));
  const quickBook = () => {
    const days = getNextSevenDays();
    const matchesGoal = (room: Room) => goal === 'quiet' ? room.capacity <= 6 : goal === 'team' ? room.capacity >= 8 : goal === 'project' ? room.equipment.includes('Projector') : room.equipment.includes('High-spec PC');
    const choice = days.flatMap((day) => timeSlots.map((slot) => ({ day, slot }))).find(({ day, slot }) => catalog.some((room) => room.status === 'available' && matchesGoal(room) && room.capacity >= 2 && !isSeedBooked(room.id, day, slot.id) && !reservations.some((booking) => booking.roomId === room.id && booking.dateKey === dayKey(day) && booking.slotId === slot.id)));
    if (!choice) { Alert.alert('Chưa tìm thấy slot', 'Tất cả phòng đang bận trong 7 ngày tới.'); return; }
    const room = catalog.find((item) => item.status === 'available' && matchesGoal(item) && item.capacity >= 2 && !isSeedBooked(item.id, choice.day, choice.slot.id) && !reservations.some((booking) => booking.roomId === item.id && booking.dateKey === dayKey(choice.day) && booking.slotId === choice.slot.id)) || recommended;
    const startAt = new Date(choice.day); const [hour, minute] = choice.slot.id.split('-')[0].split(':').map(Number); startAt.setHours(hour, minute, 0, 0);
    Alert.alert('Đặt nhanh', `App đã tự chọn slot trống gần nhất theo mục tiêu: ${goalLabel}.\n\n${room.name}\n${dateLabel(choice.day)} · ${choice.slot.label}`, [{ text: 'Xem chi tiết', onPress: () => navigation.navigate('RoomDetail', { roomId: room.id }) }, { text: 'Đặt ngay', onPress: () => { const reservation = createReservation({ roomId: room.id, roomName: room.name, building: room.building, dateKey: dayKey(choice.day), dateLabel: dateLabel(choice.day), slotId: choice.slot.id, slotLabel: choice.slot.label, startAt: startAt.toISOString() }); void scheduleBookingReminder({ roomName: room.name, slotLabel: choice.slot.label, startAt: startAt.toISOString(), passCode: reservation.passCode }); void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success); Alert.alert('Đã giữ chỗ', reservation.passCode); } }]);
  };
  return <View style={[styles.homeHero, isWide && responsiveStyles.homeHeroWide]}><MorphScene style={[styles.homeMorph, isWide && responsiveStyles.homeMorphWide]} compact /><View style={[styles.homeHeroCopy, isWide && responsiveStyles.homeHeroCopyWide]}><Text style={styles.homeHeroEyebrow}>LIVE CAMPUS</Text><Text style={styles.homeHeroTitle}>Không gian đang chuyển động.</Text><Text style={styles.homeHeroText}>Chọn mục tiêu, app lo phần tìm phòng.</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.goalRow}>{([{ id: 'quiet', label: 'Yên tĩnh' }, { id: 'team', label: 'Học nhóm' }, { id: 'project', label: 'Project' }, { id: 'pc', label: 'PC cao' }] as const).map((item) => <Pressable key={item.id} onPress={() => setGoal(item.id)} style={({ pressed }) => [styles.goalChip, goal === item.id && styles.goalChipActive, pressed && styles.pressed]} accessibilityRole="button" accessibilityState={{ selected: goal === item.id }}><Text style={[styles.goalChipText, goal === item.id && styles.goalChipTextActive]}>{item.label}</Text></Pressable>)}</ScrollView><View style={styles.homeActionRow}><Text style={styles.homeGoalText}>{goalLabel} · {recommended.name}</Text><Pressable onPress={quickBook} style={({ pressed }) => [styles.homeAction, pressed && styles.pressed]} accessibilityRole="button" accessibilityLabel="Đặt nhanh - tìm slot gần nhất" accessibilityHint="Tự chọn phòng và khung giờ trống gần nhất theo mục tiêu đang chọn"><Ionicons name="flash" size={15} color={colors.ink} /><Text style={styles.homeActionText}>Đặt nhanh</Text></Pressable><Pressable onPress={() => { if (recommended) toggleFavorite(recommended.id); }} style={({ pressed }) => [styles.favoriteAction, pressed && styles.pressed]} accessibilityRole="button" accessibilityLabel={isFavorite ? 'Bỏ lưu phòng gợi ý' : 'Lưu phòng gợi ý'} accessibilityHint="Lưu hoặc bỏ lưu phòng đang được gợi ý"><Ionicons name={isFavorite ? 'bookmark' : 'bookmark-outline'} size={15} color={colors.ink} /><Text style={styles.favoriteActionText}>{isFavorite ? 'Đã lưu' : 'Lưu'}</Text></Pressable></View></View></View>;
}

function FilterChip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) { const [hovered, setHovered] = useState(false); return <Pressable onPress={onPress} onHoverIn={() => setHovered(true)} onHoverOut={() => setHovered(false)} style={({ pressed }) => [styles.filterChip, hovered && styles.filterChipHover, active && styles.filterChipActive, pressed && styles.pressed]} accessibilityRole="button" accessibilityState={{ selected: active }}><Text style={[styles.filterChipText, (hovered || active) && styles.filterChipTextHover, active && styles.filterChipTextActive]}>{label}</Text></Pressable>; }

const RoomCard = memo(function RoomCard({ room, index, wide, onPress }: { room: Room; index: number; wide?: boolean; onPress: () => void }) { const progress = useRef(new Animated.Value(0)).current; useEffect(() => { Animated.timing(progress, { toValue: 1, duration: 260, delay: Math.min(index, 5) * 45, useNativeDriver: true }).start(); }, [index, progress]); return <Animated.View style={[{ opacity: progress, transform: [{ translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [12, 0] }) }] }, wide && { flex: 1 }]}><Pressable onPress={onPress} style={({ pressed }) => [styles.roomCard, pressed && styles.cardPressed]} accessibilityRole="button" accessibilityLabel={`Mở ${room.name}`}><RoomImage uri={room.image} style={styles.roomImage} /><View style={styles.roomCardBody}><View style={styles.roomCardTop}><View style={[styles.statusBadge, room.status === 'occupied' ? styles.occupiedBadge : styles.availableBadge]}><View style={[styles.statusDot, room.status === 'occupied' ? styles.occupiedDot : undefined]} /><Text style={[styles.statusText, room.status === 'occupied' ? styles.occupiedText : styles.availableText]}>{room.status === 'occupied' ? 'Đang sử dụng' : 'Có thể đặt'}</Text></View><Ionicons name="arrow-forward" size={19} color={colors.primary} /></View><Text style={styles.roomName}>{room.name}</Text><Text style={styles.roomMeta}>{`Tòa ${room.building} · ${room.floor} · ${room.capacity} chỗ`}</Text><View style={styles.equipmentRow}>{room.equipment.slice(0, 3).map((item) => <View key={item} style={styles.equipmentTag}><Text style={styles.equipmentTagText}>{item === 'High-spec PC' ? 'PC cao cấp' : item}</Text></View>)}</View></View></Pressable></Animated.View>; });

function RoomImage({ uri, style }: { uri: string; style?: StyleProp<ImageStyle> }) { const [failed, setFailed] = useState(false); return failed ? <LinearGradient colors={['#0B2A4A', '#0284C7']} style={[style, styles.imageFallback]}><Ionicons name="business-outline" size={36} color={colors.white} /><Text style={styles.imageFallbackText}>VKU SPACE</Text></LinearGradient> : <Image source={{ uri }} style={style} resizeMode="cover" onError={() => setFailed(true)} accessibilityLabel="Ảnh phòng học" />; }
function EmptyState() { return <View style={styles.emptyState}><Ionicons name="search-outline" size={34} color={colors.primary} /><Text style={styles.emptyTitle}>Không tìm thấy phòng</Text><Text style={styles.emptyText}>Thử đổi từ khóa hoặc bỏ bớt bộ lọc nhé.</Text></View>; }

type RoomDetailProps = NativeStackScreenProps<RootStackParamList, 'RoomDetail'>;
function RoomDetailScreen({ route, navigation }: RoomDetailProps) {
  const catalog = useRoomCatalog(); const room = catalog.find((item) => item.id === route.params.roomId) || catalog[0]; const days = useMemo(() => getNextSevenDays(), []); const reservations = useBookingStore((state) => state.reservations); const createReservation = useBookingStore((state) => state.createReservation); const [selectedDay, setSelectedDay] = useState(0); const [selectedSlotId, setSelectedSlotId] = useState<string | null>(null); const [confirmVisible, setConfirmVisible] = useState(false); const [pass, setPass] = useState<Reservation | null>(null); const selectedDate = days[selectedDay];
  const isDisabled = (slotId: string) => isSeedBooked(room.id, selectedDate, slotId) || reservations.some((booking) => booking.roomId === room.id && booking.dateKey === dayKey(selectedDate) && booking.slotId === slotId); const selectedSlot = timeSlots.find((slot) => slot.id === selectedSlotId);
  const confirmBooking = async () => { if (!selectedSlot || isDisabled(selectedSlot.id)) return; const startAt = new Date(selectedDate); const [hour, minute] = selectedSlot.id.split('-')[0].split(':').map(Number); startAt.setHours(hour, minute, 0, 0); const newReservation = createReservation({ roomId: room.id, roomName: room.name, building: room.building, dateKey: dayKey(selectedDate), dateLabel: dateLabel(selectedDate), slotId: selectedSlot.id, slotLabel: selectedSlot.label, startAt: startAt.toISOString() }); await scheduleBookingReminder({ roomName: room.name, slotLabel: selectedSlot.label, startAt: startAt.toISOString(), passCode: newReservation.passCode }); await Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success); setConfirmVisible(false); setPass(newReservation); };
  return <ScreenMotion><SafeAreaView style={styles.appScreen} edges={['top']}><ScrollView contentContainerStyle={styles.detailContent} showsVerticalScrollIndicator={false}><View style={styles.detailHeader}><Pressable onPress={() => navigation.goBack()} style={styles.iconButton} hitSlop={8} accessibilityLabel="Quay lại"><Ionicons name="arrow-back" size={22} color={colors.ink} /></Pressable><Text style={styles.detailHeaderTitle}>Chi tiết phòng</Text><Pressable onPress={() => Alert.alert('Đã lưu', 'Phòng đã được thêm vào danh sách yêu thích.')} style={styles.iconButton} hitSlop={8} accessibilityLabel="Lưu phòng"><Ionicons name="bookmark-outline" size={21} color={colors.ink} /></Pressable></View><View style={styles.heroImageWrap}><RoomImage uri={room.image} style={styles.heroImage} /><View style={styles.heroOverlay}><View style={styles.heroStatus}><View style={styles.statusDot} /><Text style={styles.heroStatusText}>Sẵn sàng đặt</Text></View></View></View><View style={styles.detailTitleRow}><View style={styles.flexOne}><Text style={styles.detailRoomName}>{room.name}</Text><Text style={styles.detailLocation}><Ionicons name="location-outline" size={15} color={colors.inkMuted} /> {`Tòa ${room.building} · ${room.floor}`}</Text></View><View style={styles.capacityCircle}><Text style={styles.capacityNumber}>{room.capacity}</Text><Text style={styles.capacityLabel}>chỗ</Text></View></View><Text style={styles.detailDescription}>{room.description}</Text><View style={styles.detailEquipment}>{room.equipment.map((item) => <View key={item} style={styles.detailEquipmentItem}><Ionicons name={item === 'AC' ? 'snow-outline' : item === 'Projector' ? 'videocam-outline' : item === 'Whiteboard' ? 'create-outline' : 'desktop-outline'} size={17} color={colors.primary} /><Text style={styles.detailEquipmentText}>{item === 'High-spec PC' ? 'PC cấu hình cao' : item}</Text></View>)}</View><Text style={styles.detailSectionTitle}>Chọn ngày học</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.dayRow}>{days.map((day, index) => <Pressable key={day.toISOString()} onPress={() => { setSelectedDay(index); setSelectedSlotId(null); }} style={[styles.dayCard, selectedDay === index && styles.dayCardActive]} accessibilityRole="button" accessibilityState={{ selected: selectedDay === index }}><Text style={[styles.dayName, selectedDay === index && styles.dayTextActive]}>{index === 0 ? 'Hôm nay' : new Intl.DateTimeFormat('vi-VN', { weekday: 'short' }).format(day).replace('.', '')}</Text><Text style={[styles.dayNumber, selectedDay === index && styles.dayTextActive]}>{day.getDate()}</Text><Text style={[styles.dayMonth, selectedDay === index && styles.dayTextActive]}>{`T${day.getMonth() + 1}`}</Text></Pressable>)}</ScrollView><View style={styles.slotHeader}><Text style={styles.detailSectionTitle}>Chọn khung giờ</Text><Text style={styles.slotTimezone}>GMT+7 · 2 giờ / slot</Text></View><View style={styles.slotGrid}>{timeSlots.map((slot) => { const disabled = isDisabled(slot.id); const selected = selectedSlotId === slot.id; return <Pressable key={slot.id} disabled={disabled} onPress={() => setSelectedSlotId(slot.id)} style={[styles.slotCard, disabled && styles.slotDisabled, selected && styles.slotSelected]} accessibilityRole="button" accessibilityState={{ disabled, selected }}><Ionicons name={disabled ? 'lock-closed-outline' : selected ? 'checkmark-circle' : 'time-outline'} size={18} color={disabled ? '#94A3B8' : selected ? colors.white : colors.primary} /><Text style={[styles.slotText, disabled && styles.slotTextDisabled, selected && styles.slotTextSelected]}>{slot.label}</Text><Text style={[styles.slotState, disabled && styles.slotTextDisabled, selected && styles.slotTextSelected]}>{disabled ? 'Đã kín' : selected ? 'Đã chọn' : 'Còn trống'}</Text></Pressable>; })}</View><Pressable disabled={!selectedSlot || isDisabled(selectedSlot.id)} onPress={() => setConfirmVisible(true)} style={({ pressed }) => [styles.bookButton, (!selectedSlot || isDisabled(selectedSlot.id)) && styles.disabledButton, pressed && styles.pressed]}><Text style={styles.primaryButtonText}>Xác nhận đặt phòng</Text><Ionicons name="arrow-forward" size={19} color={colors.white} /></Pressable></ScrollView><BookingConfirmModal visible={confirmVisible} room={room} date={selectedDate} slot={selectedSlot} onClose={() => setConfirmVisible(false)} onConfirm={confirmBooking} /><BookingPassModal reservation={pass} onClose={() => setPass(null)} /></SafeAreaView></ScreenMotion>;
}

function BookingConfirmModal({ visible, room, date, slot, onClose, onConfirm }: { visible: boolean; room: Room; date: Date; slot?: typeof timeSlots[number]; onClose: () => void; onConfirm: () => void }) { return <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}><View style={styles.modalBackdrop}><View style={styles.confirmCard}><View style={styles.modalHandle} /><View style={styles.modalIcon}><Ionicons name="calendar-outline" size={25} color={colors.primary} /></View><Text style={styles.modalTitle}>Xác nhận lượt đặt</Text><Text style={styles.modalSubtitle}>Kiểm tra thông tin trước khi giữ chỗ.</Text><View style={styles.confirmSummary}><SummaryRow icon="business-outline" label="Phòng" value={room.name} /><SummaryRow icon="calendar-outline" label="Thời gian" value={`${dateLabel(date)} · ${slot?.label || ''}`} /><SummaryRow icon="shield-checkmark-outline" label="Nhắc lịch" value="Thông báo trước 15 phút" /></View><View style={styles.modalActions}><Pressable onPress={onClose} style={styles.secondaryButton}><Text style={styles.secondaryButtonText}>Để sau</Text></Pressable><Pressable onPress={onConfirm} style={styles.primaryModalButton}><Text style={styles.primaryButtonText}>Giữ chỗ</Text></Pressable></View></View></View></Modal>; }
function SummaryRow({ icon, label, value }: { icon: keyof typeof Ionicons.glyphMap; label: string; value: string }) { return <View style={styles.summaryRow}><Ionicons name={icon} size={19} color={colors.primary} /><View style={styles.flexOne}><Text style={styles.summaryLabel}>{label}</Text><Text style={styles.summaryValue}>{value}</Text></View></View>; }
function BookingPassModal({ reservation, onClose }: { reservation: Reservation | null; onClose: () => void }) { if (!reservation) return null; return <Modal visible={Boolean(reservation)} transparent animationType="slide" onRequestClose={onClose}><View style={styles.modalBackdrop}><View style={styles.passCard}><View style={styles.passTop}><View><Text style={styles.passEyebrow}>BOOKING PASS</Text><Text style={styles.passTitle}>Đặt phòng thành công</Text></View><Pressable onPress={onClose} style={styles.closeButton} hitSlop={8} accessibilityLabel="Đóng mã QR"><Ionicons name="close" size={22} color={colors.ink} /></Pressable></View><View style={styles.qrWrap}><QRCode value={`vku://booking/${reservation.passCode}`} size={178} color={colors.ink} backgroundColor={colors.white} /></View><Text style={styles.passCode}>{reservation.passCode}</Text><Text style={styles.passRoom}>{reservation.roomName} · {reservation.slotLabel}</Text><View style={styles.passFooter}><Ionicons name="scan-outline" size={18} color={colors.mint} /><Text style={styles.passFooterText}>Đưa mã này cho cán bộ khi check-in</Text></View><Pressable onPress={onClose} style={styles.primaryModalButton}><Text style={styles.primaryButtonText}>Hoàn tất</Text></Pressable></View></View></Modal>; }

type RoomManagerProps = NativeStackScreenProps<RootStackParamList, 'RoomManager'>;
type RoomDraft = { name: string; building: Building; floor: string; capacity: string; description: string; image: string; equipment: Room['equipment'] };

function RoomManagerScreen({ navigation }: RoomManagerProps) {
  const catalog = useRoomCatalog();
  const updateRoom = useBookingStore((state) => state.updateRoom);
  const [editing, setEditing] = useState<Room | null>(null);
  const [draft, setDraft] = useState<RoomDraft | null>(null);
  const openEditor = (room: Room) => { setEditing(room); setDraft({ name: room.name, building: room.building, floor: room.floor, capacity: String(room.capacity), description: room.description, image: room.image, equipment: room.equipment }); };
  const pickImage = async () => {
    if (!draft) return;
    const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!permission.granted) { Alert.alert('Cần quyền truy cập ảnh', 'Cho phép chọn ảnh để cập nhật ảnh phòng.'); return; }
    const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], allowsEditing: true, aspect: [16, 10], quality: 0.86 });
    if (!result.canceled) setDraft({ ...draft, image: result.assets[0].uri });
  };
  const save = () => {
    if (!editing || !draft || draft.name.trim().length < 2) { Alert.alert('Thiếu thông tin', 'Tên phòng cần ít nhất 2 ký tự.'); return; }
    updateRoom(editing.id, { name: draft.name.trim(), building: draft.building, floor: draft.floor.trim() || editing.floor, capacity: Math.min(20, Math.max(2, Number(draft.capacity) || editing.capacity)), description: draft.description.trim() || editing.description, image: draft.image, equipment: draft.equipment });
    setEditing(null); setDraft(null); Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
  };
  const toggleEquipment = (item: Room['equipment'][number]) => { if (!draft) return; setDraft({ ...draft, equipment: draft.equipment.includes(item) ? draft.equipment.filter((value) => value !== item) : [...draft.equipment, item] }); };
  return <ScreenMotion><SafeAreaView style={styles.appScreen} edges={['top']}><ScrollView contentContainerStyle={styles.managerContent} showsVerticalScrollIndicator={false}><View style={styles.detailHeader}><Pressable onPress={() => navigation.goBack()} style={styles.iconButton} hitSlop={8} accessibilityLabel="Quay lại"><Ionicons name="arrow-back" size={22} color={colors.ink} /></Pressable><Text style={styles.detailHeaderTitle}>Quản lý phòng</Text><View style={styles.managerHeaderBadge}><Text style={styles.managerHeaderBadgeText}>{catalog.length}</Text></View></View><Text style={styles.managerIntro}>Cập nhật không gian campus để sinh viên luôn thấy thông tin mới nhất.</Text><View style={styles.managerTip}><Ionicons name="sparkles-outline" size={19} color={colors.primary} /><Text style={styles.managerTipText}>Thay đổi được lưu local ngay lập tức và hoạt động khi offline.</Text></View>{catalog.map((room) => <EditableRoomCard key={room.id} room={room} onPress={() => openEditor(room)} />)}</ScrollView><Modal visible={Boolean(editing && draft)} transparent animationType="slide" onRequestClose={() => { setEditing(null); setDraft(null); }}><View style={styles.modalBackdrop}><View style={styles.editorCard}><View style={styles.editorHeader}><View><Text style={styles.passEyebrow}>ROOM EDITOR</Text><Text style={styles.modalTitle}>Chỉnh sửa phòng</Text></View><Pressable onPress={() => { setEditing(null); setDraft(null); }} style={styles.closeButton} hitSlop={8} accessibilityLabel="Đóng chỉnh sửa"><Ionicons name="close" size={22} color={colors.ink} /></Pressable></View>{draft ? <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.editorScroll}><Pressable onPress={pickImage} style={styles.editImageWrap} accessibilityRole="button" accessibilityLabel="Đổi ảnh phòng"><RoomImage uri={draft.image} style={styles.editImage} /><View style={styles.editImageOverlay}><Ionicons name="camera-outline" size={18} color={colors.white} /><Text style={styles.editImageText}>Đổi ảnh</Text></View></Pressable><EditorField label="Tên phòng" value={draft.name} onChangeText={(value) => setDraft({ ...draft, name: value })} /><View style={styles.editorTwoCol}><View style={styles.editorHalf}><EditorField label="Tầng" value={draft.floor} onChangeText={(value) => setDraft({ ...draft, floor: value })} /></View><View style={styles.editorHalf}><EditorField label="Sức chứa" value={draft.capacity} onChangeText={(value) => setDraft({ ...draft, capacity: value.replace(/[^0-9]/g, '') })} keyboardType="numeric" /></View></View><Text style={styles.editorLabel}>Tòa nhà</Text><View style={styles.editorChipRow}>{(['A', 'B', 'C', 'V'] as const).map((value) => <FilterChip key={value} label={`Tòa ${value}`} active={draft.building === value} onPress={() => setDraft({ ...draft, building: value })} />)}</View><Text style={styles.editorLabel}>Thiết bị</Text><View style={styles.editorChipRow}>{(['Projector', 'Whiteboard', 'High-spec PC', 'AC'] as const).map((value) => <FilterChip key={value} label={value === 'High-spec PC' ? 'PC cao cấp' : value} active={draft.equipment.includes(value)} onPress={() => toggleEquipment(value)} />)}</View><EditorField label="Mô tả" value={draft.description} onChangeText={(value) => setDraft({ ...draft, description: value })} multiline /><Pressable onPress={save} style={styles.primaryButton}><Text style={styles.primaryButtonText}>Lưu thay đổi</Text><Ionicons name="checkmark" size={19} color={colors.white} /></Pressable></ScrollView> : null}</View></View></Modal></SafeAreaView></ScreenMotion>;
}

function EditableRoomCard({ room, onPress }: { room: Room; onPress: () => void }) { return <Pressable onPress={onPress} style={({ pressed }) => [styles.editableRoomCard, pressed && styles.pressed]} accessibilityRole="button" accessibilityLabel={`Chỉnh sửa ${room.name}`}><RoomImage uri={room.image} style={styles.editableRoomImage} /><View style={styles.editableRoomCopy}><Text style={styles.editableRoomName}>{room.name}</Text><Text style={styles.editableRoomMeta}>{`Tòa ${room.building} · ${room.floor} · ${room.capacity} chỗ`}</Text><Text style={styles.editableRoomEquipment}>{room.equipment.join(' · ')}</Text></View><View style={styles.editRoomButton}><Ionicons name="create-outline" size={18} color={colors.primary} /></View></Pressable>; }
function EditorField({ label, value, onChangeText, keyboardType, multiline = false }: { label: string; value: string; onChangeText: (value: string) => void; keyboardType?: 'default' | 'numeric'; multiline?: boolean }) { return <View style={styles.editorField}><Text style={styles.editorLabel}>{label}</Text><TextInput value={value} onChangeText={onChangeText} style={[styles.editorInput, multiline && styles.editorInputMultiline]} keyboardType={keyboardType} multiline={multiline} textAlignVertical={multiline ? 'top' : 'center'} placeholderTextColor="#94A3B8" /></View>; }

function BookingsScreen() { const reservations = useBookingStore((state) => state.reservations); const cancelReservation = useBookingStore((state) => state.cancelReservation); const [pass, setPass] = useState<Reservation | null>(null); const insets = useSafeAreaInsets(); const cancel = (reservation: Reservation) => Alert.alert('Hủy lượt đặt?', `${reservation.roomName} · ${reservation.dateLabel}`, [{ text: 'Giữ lại', style: 'cancel' }, { text: 'Hủy lượt đặt', style: 'destructive', onPress: () => cancelReservation(reservation.id) }]); return <ScreenMotion><SafeAreaView style={styles.appScreen} edges={['top']}><ScrollView contentContainerStyle={[styles.bookingContent, { paddingBottom: insets.bottom + 24 }]} showsVerticalScrollIndicator={false}><View style={styles.topBar}><View><Text style={styles.kicker}>YOUR SCHEDULE</Text><Text style={styles.screenTitle}>Lịch đặt phòng</Text></View><View style={styles.bookingCount}><Text style={styles.bookingCountNumber}>{reservations.length}</Text><Text style={styles.bookingCountLabel}>lượt đặt</Text></View></View>{reservations.length === 0 ? <View style={styles.emptyBookings}><View style={styles.emptyCalendar}><Ionicons name="calendar-outline" size={30} color={colors.primary} /></View><Text style={styles.emptyTitle}>Chưa có lượt đặt nào</Text><Text style={styles.emptyText}>Chọn một phòng phù hợp để bắt đầu buổi học tiếp theo.</Text></View> : reservations.map((item) => <BookingCard key={item.id} reservation={item} onCancel={() => cancel(item)} onViewPass={() => setPass(item)} />)}<View style={styles.offlineCard}><Ionicons name="cloud-offline-outline" size={23} color={colors.primary} /><View style={styles.flexOne}><Text style={styles.offlineCardTitle}>Lịch của bạn luôn có sẵn</Text><Text style={styles.offlineCardText}>Dữ liệu đã lưu trên thiết bị để bạn vẫn check-in khi mất mạng.</Text></View></View></ScrollView><BookingPassModal reservation={pass} onClose={() => setPass(null)} /></SafeAreaView></ScreenMotion>; }
function BookingCard({ reservation, onCancel, onViewPass }: { reservation: Reservation; onCancel: () => void; onViewPass: () => void }) {
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const [now, setNow] = useState(Date.now());
  useEffect(() => { const timer = setInterval(() => setNow(Date.now()), 30000); return () => clearInterval(timer); }, []);
  const remainingMinutes = Math.max(0, Math.floor((new Date(reservation.startAt).getTime() - now) / 60000));
  const countdown = remainingMinutes > 0 ? remainingMinutes <= 10 ? `Chuẩn bị trong ${remainingMinutes}p` : `Còn ${remainingMinutes} phút` : 'Đang diễn ra';
  const addCalendar = async () => {
    const added = await addBookingToCalendar(reservation);
    Alert.alert(added ? 'Đã thêm vào lịch' : 'Chưa cấp quyền lịch', added ? 'Bạn sẽ được nhắc theo lịch hệ thống.' : 'Hãy cấp quyền Calendar rồi thử lại.');
  };
  return <View style={styles.bookingCard}><View style={styles.bookingAccent} /><View style={styles.bookingCardContent}><View style={styles.bookingCardHeader}><View style={styles.flexOne}><Text style={styles.bookingRoom}>{reservation.roomName}</Text><Text style={styles.bookingLocation}>{`Tòa ${reservation.building} · ${reservation.dateLabel}`}</Text></View><View style={styles.countdownBadge}><Text style={styles.countdownText}>{countdown}</Text></View></View><Text style={styles.bookingSlot}>{reservation.slotLabel}</Text><View style={styles.bookingDivider} /><View style={styles.bookingActions}><Pressable onPress={onViewPass} style={styles.viewPassButton}><Ionicons name="qr-code-outline" size={17} color={colors.primary} /><Text style={styles.viewPassText}>Mở QR</Text></Pressable><Pressable onPress={() => void addCalendar()} style={styles.calendarButton}><Ionicons name="calendar-outline" size={16} color={colors.primary} /><Text style={styles.viewPassText}>Thêm lịch</Text></Pressable><Pressable onPress={() => navigation.navigate('RoomDetail', { roomId: reservation.roomId })} style={styles.repeatButton}><Ionicons name="repeat-outline" size={16} color={colors.ink} /><Text style={styles.repeatText}>Đặt lại</Text></Pressable><Pressable onPress={onCancel} style={styles.cancelButton}><Text style={styles.cancelText}>Hủy</Text></Pressable></View></View></View>;
}

type SettingsPanel = 'notifications' | 'sync' | 'privacy';

function ProfileScreen() {
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const session = useBookingStore((state) => state.session);
  const reservations = useBookingStore((state) => state.reservations);
  const setAuthSession = useBookingStore((state) => state.setAuthSession);
  const logout = useBookingStore((state) => state.logout);
  const [editVisible, setEditVisible] = useState(false);
  const [name, setName] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [settingsPanel, setSettingsPanel] = useState<SettingsPanel | null>(null);
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [logoutVisible, setLogoutVisible] = useState(false);
  const openEdit = () => { setName(session?.name || ''); setError(''); setEditVisible(true); };
  const saveProfile = async () => {
    if (!session || name.trim().length < 2) { setError('Tên cần ít nhất 2 ký tự.'); return; }
    setBusy(true); setError('');
    try {
      if (isFirebaseConfigured) {
        const next = await updateFirebaseProfileName(name);
        setAuthSession({ id: next.id, name: next.name, email: next.email, role: next.role, emailVerified: next.emailVerified });
      } else setAuthSession({ ...session, name: name.trim() });
      setEditVisible(false);
    } catch (profileError) { setError(profileError instanceof Error ? profileError.message : 'Không thể cập nhật hồ sơ.'); }
    finally { setBusy(false); }
  };
  const resendVerification = async () => { try { await resendFirebaseVerification(); Alert.alert('Đã gửi email', 'Kiểm tra hộp thư để xác minh email.'); } catch { Alert.alert('Chưa thể gửi', 'Hãy đăng nhập Firebase rồi thử lại.'); } };
  return <ScreenMotion><SafeAreaView style={styles.appScreen} edges={['top']}><ScrollView contentContainerStyle={styles.profileContent} showsVerticalScrollIndicator={false}><Text style={styles.kicker}>ACCOUNT</Text><Text style={styles.screenTitle}>Hồ sơ của bạn</Text><View style={styles.profileHero}><LinearGradient colors={['#0B2A4A', '#0284C7']} style={styles.profileGradient}><View style={styles.avatar}><Text style={styles.avatarText}>{(session?.name || 'VK').slice(0, 1).toUpperCase()}</Text></View><View style={styles.flexOne}><Text style={styles.profileName}>{session?.name || 'VKU Student'}</Text><Text style={styles.profileEmail}>{session?.email}</Text></View><Ionicons name="ellipsis-horizontal" size={22} color={colors.white} /></LinearGradient><View style={styles.profileStats}><Stat value={String(reservations.length)} label="Lượt đặt" /><Stat value="60fps" label="Hiệu năng" /><Stat value={isFirebaseConfigured ? 'LIVE' : 'OFF'} label="Đồng bộ" /></View></View><Text style={styles.detailSectionTitle}>Tài khoản</Text><ProfileRow icon="person-outline" title="Chỉnh sửa hồ sơ" subtitle="Cập nhật tên hiển thị và trạng thái email" onPress={openEdit} />{isFirebaseConfigured && !session?.emailVerified ? <ProfileRow icon="mail-unread-outline" title="Xác minh email" subtitle="Gửi lại email xác minh tài khoản" onPress={() => void resendVerification()} /> : null}<Text style={styles.detailSectionTitle}>Không gian</Text><ProfileRow icon="create-outline" title="Chỉnh sửa phòng" subtitle="Đổi tên, ảnh, sức chứa, thiết bị" onPress={() => { if (isFirebaseConfigured && session?.role !== 'admin') { Alert.alert('Chỉ dành cho admin', 'Tài khoản của bạn chưa được cấp quyền quản trị phòng.'); return; } navigation.navigate('RoomManager'); }} /><ProfileRow icon="qr-code-outline" title="Check-in booking" subtitle="Quét QR hoặc nhập mã booking" onPress={() => navigation.navigate('CheckIn')} /><Text style={styles.detailSectionTitle}>Booking cá nhân</Text><ProfileRow icon="share-social-outline" title="Chia sẻ booking" subtitle="Gửi phòng, thời gian và mã vào nhóm" onPress={() => navigation.navigate('ShareBooking')} /><ProfileRow icon="hourglass-outline" title="Danh sách chờ" subtitle="Theo dõi các slot đang đợi" onPress={() => navigation.navigate('Waitlist')} /><ProfileRow icon="star-outline" title="Đánh giá phòng" subtitle="Chia sẻ cảm nhận sau buổi học" onPress={() => navigation.navigate('Reviews')} /><Text style={styles.detailSectionTitle}>Cài đặt</Text><ProfileRow icon="notifications-outline" title="Nhắc lịch học" subtitle={notificationsEnabled ? 'Đang bật · trước 15 phút' : 'Đang tắt'} onPress={() => setSettingsPanel('notifications')} /><ProfileRow icon="cloud-done-outline" title="Đồng bộ dữ liệu" subtitle={isFirebaseConfigured ? 'Firebase realtime đang bật' : 'Đang chạy local-first'} onPress={() => setSettingsPanel('sync')} /><ProfileRow icon="shield-checkmark-outline" title="Quyền riêng tư" subtitle="Dữ liệu chỉ thuộc tài khoản của bạn" onPress={() => setSettingsPanel('privacy')} /><Pressable onPress={() => setLogoutVisible(true)} style={({ pressed }) => [styles.logoutButton, pressed && styles.pressed]} accessibilityRole="button" accessibilityLabel="Đăng xuất"><Ionicons name="log-out-outline" size={20} color={colors.danger} /><Text style={styles.logoutText}>Đăng xuất</Text></Pressable><Text style={styles.versionText}>VKU Space v1.0 · Expo SDK 57</Text></ScrollView></SafeAreaView><SettingsModal panel={settingsPanel} notificationsEnabled={notificationsEnabled} onToggleNotifications={() => setNotificationsEnabled((value) => !value)} onClose={() => setSettingsPanel(null)} /><LogoutModal visible={logoutVisible} onClose={() => setLogoutVisible(false)} onConfirm={() => { setLogoutVisible(false); void logout(); }} /><Modal visible={editVisible} transparent animationType="slide" onRequestClose={() => setEditVisible(false)}><View style={accountStyles.backdrop}><KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={accountStyles.keyboard}><View style={accountStyles.card}><View style={accountStyles.header}><View><Text style={styles.kicker}>ACCOUNT</Text><Text style={accountStyles.title}>Chỉnh sửa hồ sơ</Text></View><Pressable onPress={() => setEditVisible(false)} style={accountStyles.closeButton} accessibilityLabel="Đóng"><Ionicons name="close" size={21} color={colors.ink} /></Pressable></View><Text style={accountStyles.label}>Tên hiển thị</Text><TextInput value={name} onChangeText={setName} autoFocus style={accountStyles.input} placeholder="Nguyễn Văn A" placeholderTextColor="#94A3B8" /><Text style={accountStyles.email}>{session?.email}</Text>{error ? <Text style={accountStyles.error}>{error}</Text> : null}<Pressable onPress={() => void saveProfile()} disabled={busy} style={({ pressed }) => [styles.primaryButton, pressed && styles.pressed, busy && styles.disabledButton]}>{busy ? <ActivityIndicator color={colors.white} /> : <><Text style={styles.primaryButtonText}>Lưu hồ sơ</Text><Ionicons name="checkmark" size={19} color={colors.white} /></>}</Pressable></View></KeyboardAvoidingView></View></Modal></ScreenMotion>;
}
function Stat({ value, label }: { value: string; label: string }) { return <View style={styles.stat}><Text style={styles.statValue}>{value}</Text><Text style={styles.statLabel}>{label}</Text></View>; }
function ProfileRow({ icon, title, subtitle, onPress }: { icon: keyof typeof Ionicons.glyphMap; title: string; subtitle: string; onPress: () => void }) { return <Pressable onPress={onPress} accessibilityRole="button" style={({ pressed }) => [styles.profileRow, pressed && styles.pressed]}><View style={styles.profileRowIcon}><Ionicons name={icon} size={20} color={colors.primary} /></View><View style={styles.flexOne}><Text style={styles.profileRowTitle}>{title}</Text><Text style={styles.profileRowSubtitle}>{subtitle}</Text></View><Ionicons name="chevron-forward" size={18} color="#94A3B8" /></Pressable>; }

function SettingsModal({ panel, notificationsEnabled, onToggleNotifications, onClose }: { panel: SettingsPanel | null; notificationsEnabled: boolean; onToggleNotifications: () => void; onClose: () => void }) {
  const title = panel === 'notifications' ? 'Nhắc lịch học' : panel === 'sync' ? 'Đồng bộ dữ liệu' : 'Quyền riêng tư';
  return <Modal visible={Boolean(panel)} transparent animationType="slide" onRequestClose={onClose}><View style={settingsStyles.backdrop}><View style={settingsStyles.card}><View style={settingsStyles.header}><View><Text style={styles.kicker}>SETTINGS</Text><Text style={settingsStyles.title}>{title}</Text></View><Pressable onPress={onClose} style={settingsStyles.closeButton} accessibilityRole="button" accessibilityLabel="Đóng cài đặt"><Ionicons name="close" size={21} color={colors.ink} /></Pressable></View>{panel === 'notifications' ? <><Text style={settingsStyles.description}>Mỗi booking sẽ được nhắc trước 15 phút để bạn chủ động di chuyển đến phòng.</Text><Pressable onPress={onToggleNotifications} style={({ pressed }) => [settingsStyles.option, pressed && styles.pressed]} accessibilityRole="switch" accessibilityState={{ checked: notificationsEnabled }}><View style={settingsStyles.optionIcon}><Ionicons name="notifications-outline" size={20} color={colors.primary} /></View><View style={styles.flexOne}><Text style={settingsStyles.optionTitle}>Nhắc lịch booking</Text><Text style={settingsStyles.optionText}>{notificationsEnabled ? 'Đang bật' : 'Đang tắt'}</Text></View><View style={[settingsStyles.toggle, notificationsEnabled && settingsStyles.toggleOn]}><View style={[settingsStyles.toggleThumb, notificationsEnabled && settingsStyles.toggleThumbOn]} /></View></Pressable></> : null}{panel === 'sync' ? <><View style={settingsStyles.infoBox}><Ionicons name={isFirebaseConfigured ? 'cloud-done-outline' : 'cloud-offline-outline'} size={23} color={isFirebaseConfigured ? colors.primary : colors.inkMuted} /><View style={styles.flexOne}><Text style={settingsStyles.optionTitle}>{isFirebaseConfigured ? 'Firebase realtime đang bật' : 'Local-first đang bật'}</Text><Text style={settingsStyles.optionText}>{isFirebaseConfigured ? 'Tài khoản, booking, waitlist và review được đồng bộ theo uid.' : 'Dữ liệu vẫn lưu trên máy; thêm Firebase env để đồng bộ nhiều thiết bị.'}</Text></View></View><Text style={settingsStyles.description}>Khi mất mạng, app giữ thao tác trong cache và tự đồng bộ lại khi kết nối trở lại.</Text></> : null}{panel === 'privacy' ? <><View style={settingsStyles.infoBox}><Ionicons name="shield-checkmark-outline" size={23} color={colors.primary} /><View style={styles.flexOne}><Text style={settingsStyles.optionTitle}>Dữ liệu thuộc tài khoản của bạn</Text><Text style={settingsStyles.optionText}>Firestore Rules giới hạn profile, booking, waitlist và review theo uid.</Text></View></View><Text style={settingsStyles.description}>Mật khẩu không được lưu trong app. Bạn có thể đăng xuất bất cứ lúc nào từ màn hình hồ sơ.</Text></> : null}<Pressable onPress={onClose} style={({ pressed }) => [settingsStyles.primaryButton, pressed && styles.pressed]}><Text style={settingsStyles.primaryButtonText}>Đã hiểu</Text></Pressable></View></View></Modal>;
}

function LogoutModal({ visible, onClose, onConfirm }: { visible: boolean; onClose: () => void; onConfirm: () => void }) { return <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}><View style={settingsStyles.backdrop}><View style={settingsStyles.card}><View style={settingsStyles.confirmIcon}><Ionicons name="log-out-outline" size={23} color={colors.danger} /></View><Text style={settingsStyles.title}>Đăng xuất khỏi VKU Space?</Text><Text style={settingsStyles.description}>Booking đã lưu trên thiết bị vẫn được giữ nguyên; bạn có thể đăng nhập lại sau.</Text><View style={settingsStyles.actions}><Pressable onPress={onClose} style={({ pressed }) => [settingsStyles.secondaryButton, pressed && styles.pressed]}><Text style={settingsStyles.secondaryText}>Ở lại</Text></Pressable><Pressable onPress={onConfirm} style={({ pressed }) => [settingsStyles.dangerButton, pressed && styles.pressed]}><Text style={settingsStyles.dangerText}>Đăng xuất</Text></Pressable></View></View></View></Modal>; }

